-- Création de la base de données CREATE DATABASE IF NOT EXISTS casa_boutique; USE casa_boutique;
-- Table des utilisateurs/clients CREATE TABLE IF NOT EXISTS users ( id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, first_name VARCHAR(100), last_name VARCHAR(100), phone VARCHAR(20), address VARCHAR(255), city VARCHAR(100), country VARCHAR(100), postal_code VARCHAR(10), role ENUM('client', 'admin', 'supplier') DEFAULT 'client', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(email) );
-- Table des catégories CREATE TABLE IF NOT EXISTS categories ( id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, description TEXT, image_url VARCHAR(255), parent_id INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(parent_id) REFERENCES categories(id) );
-- Table des fournisseurs CREATE TABLE IF NOT EXISTS suppliers ( id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(255), phone VARCHAR(20), address VARCHAR(255), city VARCHAR(100), country VARCHAR(100), company_name VARCHAR(100), tax_number VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP );
-- Table des produits CREATE TABLE IF NOT EXISTS products ( id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, description TEXT, price DECIMAL(10, 2) NOT NULL, original_price DECIMAL(10, 2), category_id INT, supplier_id INT, stock INT DEFAULT 0, image_url VARCHAR(255), images JSON, discount_percent DECIMAL(5, 2) DEFAULT 0, is_popular BOOLEAN DEFAULT FALSE, is_promotion BOOLEAN DEFAULT FALSE, views INT DEFAULT 0, rating DECIMAL(3, 2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(supplier_id) REFERENCES suppliers(id), INDEX(name), INDEX(category_id), FULLTEXT(name, description) );
-- Table du panier CREATE TABLE IF NOT EXISTS cart_items ( id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL DEFAULT 1, added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, UNIQUE KEY(user_id, product_id) );
-- Table des commandes CREATE TABLE IF NOT EXISTS orders ( id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, order_number VARCHAR(50) UNIQUE NOT NULL, total_amount DECIMAL(10, 2) NOT NULL, tax DECIMAL(10, 2) DEFAULT 0, shipping_cost DECIMAL(10, 2) DEFAULT 0, discount_amount DECIMAL(10, 2) DEFAULT 0, status ENUM('pending', 'confirmed', 'shipped', 'delivered', 'cancelled') DEFAULT 'pending', shipping_address VARCHAR(255), shipping_city VARCHAR(100), shipping_country VARCHAR(100), shipping_postal_code VARCHAR(10), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), INDEX(user_id), INDEX(status) );
-- Table des articles de commande CREATE TABLE IF NOT EXISTS order_items ( id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, product_id INT NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10, 2) NOT NULL, total_price DECIMAL(10, 2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) );
-- Table des paiements CREATE TABLE IF NOT EXISTS payments ( id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, user_id INT NOT NULL, amount DECIMAL(10, 2) NOT NULL, payment_method ENUM('paytech', 'wave', 'orange_money', 'card', 'bank_transfer') NOT NULL, payment_status ENUM('pending', 'completed', 'failed', 'refunded') DEFAULT 'pending', transaction_id VARCHAR(255), payment_reference VARCHAR(255), paid_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(transaction_id) );
-- Table des factures CREATE TABLE IF NOT EXISTS invoices ( id INT PRIMARY KEY AUTO_INCREMENT, invoice_number VARCHAR(50) UNIQUE NOT NULL, order_id INT NOT NULL, user_id INT NOT NULL, amount DECIMAL(10, 2) NOT NULL, tax DECIMAL(10, 2) DEFAULT 0, status ENUM('generated', 'sent', 'paid') DEFAULT 'generated', sent_by ENUM('email', 'whatsapp', 'both') DEFAULT 'email', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(user_id) REFERENCES users(id) );
-- Table des avis/commentaires CREATE TABLE IF NOT EXISTS reviews ( id INT PRIMARY KEY AUTO_INCREMENT, product_id INT NOT NULL, user_id INT NOT NULL, rating INT NOT NULL CHECK (rating >= 1 AND rating <= 5), comment TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE );
-- Index supplémentaires pour les performances CREATE INDEX idx_products_category ON products(category_id); CREATE INDEX idx_products_supplier ON products(supplier_id); CREATE INDEX idx_orders_user ON orders(user_id); CREATE INDEX idx_payments_order ON payments(order_id); CREATE INDEX idx_cart_user ON cart_items(user_id);

const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const { v4: uuidv4 } = require('uuid');
const router = express.Router();
const auth = require('../middleware/auth');

// Register
router.post('/register', async (req, res) => {
  try {
    const { nom, email, telephone, password } = req.body;
    const pool = req.pool;

    // Vérifier si l'email existe déjà
    const [existingUser] = await pool.query('SELECT * FROM clients WHERE email = ?', [email]);
    if (existingUser.length > 0) {
      return res.status(400).json({ message: 'Email déjà utilisé' });
    }

    // Hasher le mot de passe
    const hashedPassword = await bcrypt.hash(password, 10);
    const userId = uuidv4();

    // Insérer l'utilisateur
    await pool.query(
      'INSERT INTO clients (id, nom, email, telephone, password, role, created_at) VALUES (?, ?, ?, ?, ?, ?, NOW())',
      [userId, nom, email, telephone, hashedPassword, 'client']
    );

    // Générer le token
    const token = jwt.sign({ id: userId, role: 'client' }, process.env.JWT_SECRET || 'secret');

    res.status(201).json({
      user: { id: userId, nom, email, telephone, role: 'client' },
      token
    });
  } catch (error) {
    console.error('Erreur d\'inscription:', error);
    res.status(500).json({ message: 'Erreur lors de l\'inscription' });
  }
});

// Login
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const pool = req.pool;

    // Trouver l'utilisateur
    const [users] = await pool.query('SELECT * FROM clients WHERE email = ?', [email]);
    if (users.length === 0) {
      return res.status(401).json({ message: 'Email ou mot de passe incorrect' });
    }

    const user = users[0];

    // Vérifier le mot de passe
    const passwordMatch = await bcrypt.compare(password, user.password);
    if (!passwordMatch) {
      return res.status(401).json({ message: 'Email ou mot de passe incorrect' });
    }

    // Générer le token
    const token = jwt.sign(
      { id: user.id, role: user.role },
      process.env.JWT_SECRET || 'secret'
    );

    res.json({
      user: {
        id: user.id,
        nom: user.nom,
        email: user.email,
        telephone: user.telephone,
        role: user.role
      },
      token
    });
  } catch (error) {
    console.error('Erreur de connexion:', error);
    res.status(500).json({ message: 'Erreur lors de la connexion' });
  }
});

// Get current user
router.get('/me', auth, async (req, res) => {
  try {
    const pool = req.pool;
    const [users] = await pool.query('SELECT * FROM clients WHERE id = ?', [req.userId]);

    if (users.length === 0) {
      return res.status(404).json({ message: 'Utilisateur non trouvé' });
    }

    const user = users[0];
    res.json({
      id: user.id,
      nom: user.nom,
      email: user.email,
      telephone: user.telephone,
      role: user.role
    });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Update profile
router.put('/profile', auth, async (req, res) => {
  try {
    const { nom, email, telephone } = req.body;
    const pool = req.pool;

    await pool.query(
      'UPDATE clients SET nom = ?, email = ?, telephone = ? WHERE id = ?',
      [nom, email, telephone, req.userId]
    );

    res.json({ message: 'Profil mis à jour' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const router = express.Router();
const auth = require('../middleware/auth');

// Inscription
router.post('/register', async (req, res) => {
  try {
    const { email, password, first_name, last_name, phone } = req.body;
    const pool = req.pool;

    // Vérifier si l'email existe déjà
    const [existingUser] = await pool.query('SELECT id FROM users WHERE email = ?', [email]);
    if (existingUser.length > 0) {
      return res.status(400).json({ message: 'Email déjà utilisé' });
    }

    // Hasher le mot de passe
    const hashedPassword = await bcrypt.hash(password, 10);

    // Insérer l'utilisateur
    const [result] = await pool.query(
      'INSERT INTO users (email, password, first_name, last_name, phone, role) VALUES (?, ?, ?, ?, ?, ?)',
      [email, hashedPassword, first_name, last_name, phone || null, 'client']
    );

    // Générer le token
    const token = jwt.sign(
      { id: result.insertId, email, role: 'client' },
      process.env.JWT_SECRET || 'secret',
      { expiresIn: '30d' }
    );

    res.status(201).json({
      message: 'Utilisateur créé avec succès',
      user: {
        id: result.insertId,
        email,
        first_name,
        last_name,
        role: 'client'
      },
      token
    });
  } catch (error) {
    console.error('Erreur lors de l\'inscription:', error);
    res.status(500).json({ message: 'Erreur lors de l\'inscription' });
  }
});

// Connexion
router.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const pool = req.pool;

    // Trouver l'utilisateur
    const [users] = await pool.query('SELECT id, password, role, first_name, last_name, email FROM users WHERE email = ?', [email]);
    if (users.length === 0) {
      return res.status(401).json({ message: 'Email ou mot de passe incorrect' });
    }

    const user = users[0];

    // Vérifier le mot de passe
    const passwordMatch = await bcrypt.compare(password, user.password);
    if (!passwordMatch) {
      return res.status(401).json({ message: 'Email ou mot de passe incorrect' });
    }

    // Générer le token
    const token = jwt.sign(
      { id: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET || 'secret',
      { expiresIn: '30d' }
    );

    res.json({
      message: 'Connexion réussie',
      user: {
        id: user.id,
        email: user.email,
        first_name: user.first_name,
        last_name: user.last_name,
        role: user.role
      },
      token
    });
  } catch (error) {
    console.error('Erreur lors de la connexion:', error);
    res.status(500).json({ message: 'Erreur lors de la connexion' });
  }
});

// Récupérer le profil de l'utilisateur
router.get('/me', auth, async (req, res) => {
  try {
    const pool = req.pool;
    const [users] = await pool.query(
      'SELECT id, email, first_name, last_name, phone, address, city, country, postal_code, role FROM users WHERE id = ?',
      [req.userId]
    );

    if (users.length === 0) {
      return res.status(404).json({ message: 'Utilisateur non trouvé' });
    }

    res.json(users[0]);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Mettre à jour le profil
router.put('/profile', auth, async (req, res) => {
  try {
    const { first_name, last_name, phone, address, city, country, postal_code } = req.body;
    const pool = req.pool;

    await pool.query(
      'UPDATE users SET first_name = ?, last_name = ?, phone = ?, address = ?, city = ?, country = ?, postal_code = ? WHERE id = ?',
      [first_name, last_name, phone, address, city, country, postal_code, req.userId]
    );

    res.json({ message: 'Profil mis à jour avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Changer le mot de passe
router.post('/change-password', auth, async (req, res) => {
  try {
    const { oldPassword, newPassword } = req.body;
    const pool = req.pool;

    // Récupérer l'utilisateur
    const [users] = await pool.query('SELECT password FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0) {
      return res.status(404).json({ message: 'Utilisateur non trouvé' });
    }

    // Vérifier l'ancien mot de passe
    const passwordMatch = await bcrypt.compare(oldPassword, users[0].password);
    if (!passwordMatch) {
      return res.status(401).json({ message: 'Mot de passe actuel incorrect' });
    }

    // Hasher le nouveau mot de passe
    const hashedPassword = await bcrypt.hash(newPassword, 10);

    // Mettre à jour
    await pool.query('UPDATE users SET password = ? WHERE id = ?', [hashedPassword, req.userId]);

    res.json({ message: 'Mot de passe changé avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');

// Récupérer le panier de l'utilisateur
router.get('/', auth, async (req, res) => {
  try {
    const pool = req.pool;

    const [cartItems] = await pool.query(
      `SELECT c.*, p.name, p.price, p.image_url, p.stock
       FROM cart_items c
       JOIN products p ON c.product_id = p.id
       WHERE c.user_id = ?
       ORDER BY c.added_at DESC`,
      [req.userId]
    );

    // Calculer le total
    const total = cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    res.json({ items: cartItems, total });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Ajouter un produit au panier
router.post('/add', auth, async (req, res) => {
  try {
    const { product_id, quantity = 1 } = req.body;
    const pool = req.pool;

    // Vérifier que le produit existe et qu'il y a du stock
    const [products] = await pool.query('SELECT stock FROM products WHERE id = ?', [product_id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    if (products[0].stock < quantity) {
      return res.status(400).json({ message: 'Stock insuffisant' });
    }

    // Vérifier si le produit est déjà dans le panier
    const [existingItem] = await pool.query(
      'SELECT id, quantity FROM cart_items WHERE user_id = ? AND product_id = ?',
      [req.userId, product_id]
    );

    if (existingItem.length > 0) {
      // Mettre à jour la quantité
      await pool.query(
        'UPDATE cart_items SET quantity = quantity + ? WHERE user_id = ? AND product_id = ?',
        [quantity, req.userId, product_id]
      );
    } else {
      // Ajouter un nouvel article
      await pool.query(
        'INSERT INTO cart_items (user_id, product_id, quantity) VALUES (?, ?, ?)',
        [req.userId, product_id, quantity]
      );
    }

    res.json({ message: 'Produit ajouté au panier' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Mettre à jour la quantité d'un produit
router.put('/update/:product_id', auth, async (req, res) => {
  try {
    const { product_id } = req.params;
    const { quantity } = req.body;
    const pool = req.pool;

    if (quantity <= 0) {
      // Supprimer l'article si la quantité est 0 ou négative
      await pool.query('DELETE FROM cart_items WHERE user_id = ? AND product_id = ?', [req.userId, product_id]);
      return res.json({ message: 'Produit supprimé du panier' });
    }

    // Vérifier que le produit existe et qu'il y a du stock
    const [products] = await pool.query('SELECT stock FROM products WHERE id = ?', [product_id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    if (products[0].stock < quantity) {
      return res.status(400).json({ message: 'Stock insuffisant' });
    }

    // Mettre à jour la quantité
    await pool.query(
      'UPDATE cart_items SET quantity = ? WHERE user_id = ? AND product_id = ?',
      [quantity, req.userId, product_id]
    );

    res.json({ message: 'Quantité mise à jour' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Supprimer un produit du panier
router.delete('/remove/:product_id', auth, async (req, res) => {
  try {
    const { product_id } = req.params;
    const pool = req.pool;

    await pool.query('DELETE FROM cart_items WHERE user_id = ? AND product_id = ?', [req.userId, product_id]);

    res.json({ message: 'Produit supprimé du panier' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Vider le panier
router.delete('/clear', auth, async (req, res) => {
  try {
    const pool = req.pool;

    await pool.query('DELETE FROM cart_items WHERE user_id = ?', [req.userId]);

    res.json({ message: 'Panier vidé' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');

// Récupérer toutes les catégories
router.get('/', async (req, res) => {
  try {
    const pool = req.pool;
    const [categories] = await pool.query('SELECT * FROM categories WHERE parent_id IS NULL ORDER BY name');
    res.json(categories);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer une catégorie avec ses sous-catégories
router.get('/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const pool = req.pool;

    const [categories] = await pool.query('SELECT * FROM categories WHERE id = ?', [id]);
    if (categories.length === 0) {
      return res.status(404).json({ message: 'Catégorie non trouvée' });
    }

    const [subcategories] = await pool.query('SELECT * FROM categories WHERE parent_id = ?', [id]);

    res.json({ ...categories[0], subcategories });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Créer une catégorie (admin)
router.post('/', auth, async (req, res) => {
  try {
    const { name, description, image_url, parent_id } = req.body;
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [result] = await pool.query(
      'INSERT INTO categories (name, description, image_url, parent_id) VALUES (?, ?, ?, ?)',
      [name, description, image_url, parent_id || null]
    );

    res.status(201).json({ message: 'Catégorie créée', id: result.insertId });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Mettre à jour une catégorie (admin)
router.put('/:id', auth, async (req, res) => {
  try {
    const { id } = req.params;
    const { name, description, image_url } = req.body;
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    await pool.query(
      'UPDATE categories SET name = ?, description = ?, image_url = ? WHERE id = ?',
      [name, description, image_url, id]
    );

    res.json({ message: 'Catégorie mise à jour' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Supprimer une catégorie (admin)
router.delete('/:id', auth, async (req, res) => {
  try {
    const { id } = req.params;
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    // Vérifier qu'il n'y a pas de produits liés
    const [products] = await pool.query('SELECT id FROM products WHERE category_id = ?', [id]);
    if (products.length > 0) {
      return res.status(400).json({ message: 'Impossible de supprimer la catégorie, elle contient des produits' });
    }

    await pool.query('DELETE FROM categories WHERE id = ?', [id]);

    res.json({ message: 'Catégorie supprimée' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');

// Récupérer le profil du client
router.get('/profile', auth, async (req, res) => {
  try {
    const pool = req.pool;
    const [users] = await pool.query(
      'SELECT id, email, first_name, last_name, phone, address, city, country, postal_code, role, created_at FROM users WHERE id = ?',
      [req.userId]
    );

    if (users.length === 0) {
      return res.status(404).json({ message: 'Profil non trouvé' });
    }

    res.json(users[0]);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Mettre à jour le profil du client
router.put('/profile', auth, async (req, res) => {
  try {
    const { first_name, last_name, phone, address, city, country, postal_code } = req.body;
    const pool = req.pool;

    await pool.query(
      'UPDATE users SET first_name = ?, last_name = ?, phone = ?, address = ?, city = ?, country = ?, postal_code = ? WHERE id = ?',
      [first_name, last_name, phone, address, city, country, postal_code, req.userId]
    );

    res.json({ message: 'Profil mis à jour avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer les commandes du client
router.get('/orders', auth, async (req, res) => {
  try {
    const pool = req.pool;

    const [orders] = await pool.query(
      'SELECT * FROM orders WHERE user_id = ? ORDER BY created_at DESC',
      [req.userId]
    );

    res.json(orders);
  } catch (error) {
    console.error('Erreur:', error);
