// Create order
router.post('/', auth, async (req, res) => {
  try {
    const pool = req.pool;
    const { items, montant_total, nom_client, email, telephone, adresse, ville, codePostal, notes } = req.body;

    const orderId = uuidv4();

    // Créer la commande
    await pool.query(
      'INSERT INTO commandes (id, client_id, nom_client, email, telephone, adresse, ville, code_postal, montant_total, notes, statut, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NOW())',
      [orderId, req.userId, nom_client, email, telephone, adresse, ville, codePostal, montant_total, notes, 'pending']
    );

    // Ajouter les items
    for (const item of items) {
      await pool.query(
        'INSERT INTO commande_items (id, commande_id, product_id, quantity, prix) VALUES (?, ?, ?, ?, ?)',
        [uuidv4(), orderId, item.product_id, item.quantity, item.prix]
      );
    }

    res.status(201).json({ id: orderId, message: 'Commande créée' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

