// Initiate payment
router.post('/initiate', auth, async (req, res) => {
  try {
    const { Amount, Description } = req.body;

    // PayTech API configuration
    const apiKey = process.env.PAYTECH_API_KEY;
    const apiUrl = process.env.PAYTECH_URL || 'https://api.paytech.sn/api/payment/send-invoice/';

    const paymentData = {
      api_key: apiKey,
      amount: Amount,
      currency: 'XOF',
      description: Description,
      client_id: req.userId,
      return_url: `${process.env.FRONTEND_URL}/checkout/success`,
      cancel_url: `${process.env.FRONTEND_URL}/checkout/cancel`
    };

    // Appel à PayTech
    const response = await axios.post(apiUrl, paymentData);

    res.json({
      payment_url: response.data.payment_url || response.data.redirect_url,
      transaction_id: response.data.transaction_id
    });
  } catch (error) {
    console.error('Erreur PayTech:', error.message);
    res.status(500).json({ message: 'Erreur lors de l\'initiation du paiement' });
  }
});

