});

// Create product (Admin only)
router.post('/', auth, async (req, res) => {
  try {
    if (req.userRole !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const { nom, description, prix, categorie, image, en_stock, supplier_id } = req.body;
    const pool = req.pool;
    const productId = uuidv4();

    await pool.query(
      'INSERT INTO produits (id, nom, description, prix, categorie, image, en_stock, supplier_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, NOW())',
      [productId, nom, description, prix, categorie, image, en_stock, supplier_id]
    );

    res.status(201).json({ id: productId, message: 'Produit créé' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

