      return res.status(403).json({ message: 'Accès refusé' });
    }

    const { nom, description, prix, categorie, image, en_stock } = req.body;
    const pool = req.pool;

    await pool.query(
      'UPDATE produits SET nom = ?, description = ?, prix = ?, categorie = ?, image = ?, en_stock = ? WHERE id = ?',
