const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');

// Récupérer tous les produits avec filtres
router.get('/', async (req, res) => {
  try {
    const { category_id, search, sort, limit = 20, offset = 0, supplier_id } = req.query;
    const pool = req.pool;
    let query = 'SELECT * FROM products WHERE 1=1';
    const params = [];

    if (category_id) {
      query += ' AND category_id = ?';
      params.push(category_id);
    }

    if (supplier_id) {
      query += ' AND supplier_id = ?';
      params.push(supplier_id);
    }

    if (search) {
      query += ' AND (name LIKE ? OR description LIKE ?)';
      const searchTerm = `%${search}%`;
      params.push(searchTerm, searchTerm);
    }

    // Tri
    switch (sort) {
      case 'price_asc':
        query += ' ORDER BY price ASC';
        break;
      case 'price_desc':
        query += ' ORDER BY price DESC';
        break;
      case 'newest':
        query += ' ORDER BY created_at DESC';
        break;
      case 'popular':
        query += ' ORDER BY views DESC';
        break;
      case 'rating':
        query += ' ORDER BY rating DESC';
        break;
      default:
        query += ' ORDER BY created_at DESC';
    }

    query += ' LIMIT ? OFFSET ?';
    params.push(parseInt(limit), parseInt(offset));

    const [products] = await pool.query(query, params);

    res.json(products);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer un produit spécifique
router.get('/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const pool = req.pool;

    const [products] = await pool.query('SELECT * FROM products WHERE id = ?', [id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    // Récupérer les avis
    const [reviews] = await pool.query('SELECT * FROM reviews WHERE product_id = ?', [id]);

    res.json({ ...products[0], reviews });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Créer un produit (admin/supplier)
router.post('/', auth, async (req, res) => {
  try {
    const { name, description, price, original_price, category_id, stock, image_url, images, discount_percent } = req.body;
    const pool = req.pool;

    // Vérifier les permissions
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || (users[0].role !== 'admin' && users[0].role !== 'supplier')) {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const supplier_id = users[0].role === 'supplier' ? req.userId : null;

    const [result] = await pool.query(
      'INSERT INTO products (name, description, price, original_price, category_id, supplier_id, stock, image_url, images, discount_percent) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [name, description, price, original_price || null, category_id, supplier_id, stock, image_url, JSON.stringify(images || []), discount_percent || 0]
    );

    res.status(201).json({
      message: 'Produit créé avec succès',
      id: result.insertId
    });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Mettre à jour un produit
router.put('/:id', auth, async (req, res) => {
  try {
    const { id } = req.params;
    const { name, description, price, original_price, category_id, stock, image_url, images, discount_percent } = req.body;
    const pool = req.pool;

    // Vérifier les permissions
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || (users[0].role !== 'admin' && users[0].role !== 'supplier')) {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [products] = await pool.query('SELECT supplier_id FROM products WHERE id = ?', [id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    // Vérifier que le supplier ne peut modifier que ses propres produits
    if (users[0].role === 'supplier' && products[0].supplier_id !== req.userId) {
      return res.status(403).json({ message: 'Vous ne pouvez modifier que vos propres produits' });
    }

    await pool.query(
      'UPDATE products SET name = ?, description = ?, price = ?, original_price = ?, category_id = ?, stock = ?, image_url = ?, images = ?, discount_percent = ? WHERE id = ?',
      [name, description, price, original_price || null, category_id, stock, image_url, JSON.stringify(images || []), discount_percent || 0, id]
    );

    res.json({ message: 'Produit mis à jour avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Supprimer un produit
router.delete('/:id', auth, async (req, res) => {
  try {
    const { id } = req.params;
    const pool = req.pool;

    // Vérifier les permissions
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || (users[0].role !== 'admin' && users[0].role !== 'supplier')) {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [products] = await pool.query('SELECT supplier_id FROM products WHERE id = ?', [id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    if (users[0].role === 'supplier' && products[0].supplier_id !== req.userId) {
      return res.status(403).json({ message: 'Vous ne pouvez supprimer que vos propres produits' });
    }

    await pool.query('DELETE FROM products WHERE id = ?', [id]);

    res.json({ message: 'Produit supprimé avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Ajouter un avis
router.post('/:id/reviews', auth, async (req, res) => {
  try {
    const { id } = req.params;
    const { rating, comment } = req.body;
    const pool = req.pool;

    // Vérifier que le produit existe
    const [products] = await pool.query('SELECT id FROM products WHERE id = ?', [id]);
    if (products.length === 0) {
      return res.status(404).json({ message: 'Produit non trouvé' });
    }

    // Ajouter l'avis
    await pool.query(
      'INSERT INTO reviews (product_id, user_id, rating, comment) VALUES (?, ?, ?, ?)',
      [id, req.userId, rating, comment]
    );

    // Mettre à jour la note moyenne du produit
    const [reviews] = await pool.query('SELECT AVG(rating) as avg_rating FROM reviews WHERE product_id = ?', [id]);
    const avgRating = reviews[0].avg_rating || 0;
    await pool.query('UPDATE products SET rating = ? WHERE id = ?', [avgRating, id]);

    res.status(201).json({ message: 'Avis ajouté avec succès' });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');

// Récupérer les statistiques du tableau de bord
router.get('/dashboard', auth, async (req, res) => {
  try {
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    // Nombre total de clients
    const [clientsCount] = await pool.query('SELECT COUNT(*) as count FROM users WHERE role = "client"');

    // Nombre total de produits
    const [productsCount] = await pool.query('SELECT COUNT(*) as count FROM products');

    // Nombre total de catégories
    const [categoriesCount] = await pool.query('SELECT COUNT(*) as count FROM categories WHERE parent_id IS NULL');

    // Nombre total de commandes
    const [ordersCount] = await pool.query('SELECT COUNT(*) as count FROM orders');

    // Montant total des ventes
    const [totalSales] = await pool.query('SELECT SUM(total_amount) as total FROM orders');

    // Nombre de commandes par statut
    const [ordersByStatus] = await pool.query(
      'SELECT status, COUNT(*) as count FROM orders GROUP BY status'
    );

    // Paiements complétés
    const [completedPayments] = await pool.query(
      'SELECT COUNT(*) as count FROM payments WHERE payment_status = "completed"'
    );

    // Paiements en attente
    const [pendingPayments] = await pool.query(
      'SELECT COUNT(*) as count FROM payments WHERE payment_status = "pending"'
    );

    res.json({
      clients: clientsCount[0].count,
      products: productsCount[0].count,
      categories: categoriesCount[0].count,
      orders: ordersCount[0].count,
      totalSales: totalSales[0].total || 0,
      ordersByStatus,
      completedPayments: completedPayments[0].count,
      pendingPayments: pendingPayments[0].count
    });
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer les ventes par jour (derniers 30 jours)
router.get('/sales-by-day', auth, async (req, res) => {
  try {
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [sales] = await pool.query(
      `SELECT DATE(created_at) as date, SUM(total_amount) as total, COUNT(*) as count
       FROM orders
       WHERE created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY)
       GROUP BY DATE(created_at)
       ORDER BY date ASC`
    );

    res.json(sales);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer les produits les plus vendus
router.get('/top-products', auth, async (req, res) => {
  try {
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [topProducts] = await pool.query(
      `SELECT p.id, p.name, p.price, SUM(oi.quantity) as total_sold, SUM(oi.total_price) as revenue
       FROM products p
       JOIN order_items oi ON p.id = oi.product_id
       GROUP BY p.id
       ORDER BY total_sold DESC
       LIMIT 10`
    );

    res.json(topProducts);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer les revenus par catégorie
router.get('/revenue-by-category', auth, async (req, res) => {
  try {
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [revenue] = await pool.query(
      `SELECT c.name, SUM(oi.total_price) as revenue, COUNT(DISTINCT oi.order_id) as orders
       FROM categories c
       JOIN products p ON c.id = p.category_id
       JOIN order_items oi ON p.id = oi.product_id
       GROUP BY c.id
       ORDER BY revenue DESC`
    );

    res.json(revenue);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

// Récupérer les meilleurs clients
router.get('/top-customers', auth, async (req, res) => {
  try {
    const pool = req.pool;

    // Vérifier que l'utilisateur est admin
    const [users] = await pool.query('SELECT role FROM users WHERE id = ?', [req.userId]);
    if (users.length === 0 || users[0].role !== 'admin') {
      return res.status(403).json({ message: 'Accès refusé' });
    }

    const [topCustomers] = await pool.query(
      `SELECT u.id, u.first_name, u.last_name, u.email, COUNT(o.id) as orders, SUM(o.total_amount) as total_spent
       FROM users u
       JOIN orders o ON u.id = o.user_id
       GROUP BY u.id
       ORDER BY total_spent DESC
       LIMIT 10`
    );

    res.json(topCustomers);
  } catch (error) {
    console.error('Erreur:', error);
    res.status(500).json({ message: 'Erreur serveur' });
  }
});

module.exports = router;

