import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { productService } from '../services/api';
import ProductCard from '../components/ProductCard';
import './HomePage.css';

function HomePage() {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const productsRes = await productService.getAll();
      setProducts(productsRes.data);

      // Extraire les catégories uniques
      const uniqueCategories = [...new Set(productsRes.data.map(p => p.categorie))];
      setCategories(uniqueCategories);
    } catch (error) {
      console.error('Erreur lors du chargement:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="homepage">
      {/* Bannière principale */}
      <section className="banner bg-gradient text-white text-center py-5">
        <div className="container">
          <h1 className="display-4 fw-bold mb-3">
            Bienvenue à Casa Boutique
          </h1>
          <p className="lead mb-4">
            Découvrez les meilleurs produits avec les meilleures offres
          </p>
          <Link to="/boutique" className="btn btn-light btn-lg">
            Découvrir la boutique
          </Link>
        </div>
      </section>

      {/* Catégories */}
      <section className="categories py-5">
        <div className="container">
          <h2 className="mb-4">Catégories</h2>
          <div className="row">
            {categories.map((category, index) => (
              <div key={index} className="col-md-4 mb-3">
                <Link to={`/boutique?category=${category}`} className="category-card">
                  <div className="card text-center p-4">
                    <div className="category-icon mb-3">
                      {category === 'Électronique' && ''}
                      {category === 'Vêtements' && ''}
                      {category === 'Maison' && ''}
                      {category === 'Sports' && '⚽'}
                      {category === 'Beauté' && ''}
                      {!['Électronique', 'Vêtements', 'Maison', 'Sports', 'Beauté'].includes(category) && ''}
                    </div>
                    <h5>{category}</h5>
                  </div>
                </Link>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Produits populaires */}
      <section className="popular-products py-5 bg-light">
        <div className="container">
          <h2 className="mb-4">Produits populaires</h2>
          {loading ? (
            <div className="text-center">
              <div className="spinner-border" role="status">
                <span className="visually-hidden">Chargement...</span>
              </div>
            </div>
          ) : (
            <div className="row">
              {products.slice(0, 6).map(product => (
                <div key={product.id} className="col-md-4 mb-4">
                  <ProductCard product={product} />
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      {/* Produits récents */}
      <section className="recent-products py-5">
        <div className="container">
          <h2 className="mb-4">Produits récents</h2>
          <div className="row">
            {products.slice(-6).map(product => (
              <div key={product.id} className="col-md-4 mb-4">
                <ProductCard product={product} />
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Promotions */}
      <section className="promotions py-5 bg-primary text-white text-center">
        <div className="container">
          <h2 className="mb-4">Offres exceptionnelles</h2>
          <div className="row">
            <div className="col-md-6 mb-3">
              <div className="promo-card p-4">
                <h3>Jusqu'à 50% de réduction</h3>
                <p className="lead">Sur tous les électroniques</p>
              </div>
            </div>
            <div className="col-md-6">
              <div className="promo-card p-4">
                <h3>Livraison gratuite</h3>
                <p className="lead">À partir de 5000 FCFA</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Avantages */}
      <section className="advantages py-5">
        <div className="container">
          <div className="row text-center">
            <div className="col-md-3">
              <h4> Livraison rapide</h4>
              <p>Reçu en 24-48 heures</p>
            </div>
            <div className="col-md-3">
              <h4> Paiement sécurisé</h4>
              <p>Plusieurs modes de paiement</p>
            </div>
            <div className="col-md-3">
              <h4> Retours faciles</h4>
              <p>Satisfait ou remboursé</p>
            </div>
            <div className="col-md-3">
              <h4> Support 24/7</h4>
              <p>Nous sommes toujours là</p>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

export default HomePage;

